#define PieceRecords18DA 0xAE85 /* overlay 18DA's tile piece records, 16 bytes by OBJ_3040: hit box width and height, tile script, entry row */
#define ContinueStepsRichter 0x800B /* the continue screen's steps by sub-mode for Richter, a word each */
#define ContinueStepsMaria 0x801A /* the continue screen's steps by sub-mode for Maria, a word each */
#define ContinueMovesTwo 0x8492 /* the next choice of two: by choice for UP, by choice plus 2 for the other keys */
#define ContinueMovesThree 0x8496 /* the next choice of three: by choice for UP, by choice plus 2 for the other keys */
#define ContinueCursorRows 0x849B /* the cursor's Y by choice */
#define ContinueVoices 0x849E /* the voice a choice sounds by character */
#define ContinueBlinkScripts 0x84BE /* the cursor's blink scripts by step, ten */
#define TimeSlowMode 0x3BD8 /* the time-slowing mode RunObjects reads (OBJ_PACE): 0 off, 1 or 2 its pattern; the stage's sub-steps clear it and restart the fade */
#define StageSequenceToggle 0x35BF /* the stage's opening sequence's toggle (StepStageSequence); set, the pause holds; the same byte as StageVar35BE+1 */
#define StageSequenceDelay 0x3617 /* frames before the stage's opening sequence runs (StepStageFrame); the pause clears it; the same byte as StageVar3616+1 */
#define ScrollColumnBlocks 0x3E66 /* a layer entry's column: bits 0 to 6 the blocks a column draws, bit 7 the offset added (DrawBlockColumn); the same byte as Scroll3E66 */
#define SectionOrder 0x9B90 /* the stage's section record (zField83) by its step through the stage (zField82) */
#define EffectColumnBlocks 0xA994 /* the second set-up's ScrollColumnBlocks of entry 0 by raster effect (StageSetUpScrollByEffect) */
#define EffectSecondSetUp 0x88CE /* not zero when the section's raster effect has a second set-up (InitStage), by effect */
#define MariaFootYByState 0xA118 /* the row below her the spike check reads, by state (MariaSpikeBelow) */
#define MariaStartHandlers 0xA131 /* four words by zField8A: a new run, the health, the stand, the clear (MariaStart) */
#define MariaAnimationSounds 0xC1A8 /* the list started on the player's channel, by animation (MariaAnimationSound) */
#define MariaAnimationHitboxIndex 0xC200 /* hitbox index by animation (MariaFrame) */
#define MariaAnimationHitbox 0xC258 /* her hitboxes, four bytes each: X and Y offsets, half width and half height (MariaFrame) */
#define PlayerItemFirstUse 0x3BD6 /* not zero: the item in hand has not been used; its first use starts its sound list and script and clears this (set at the start and when the pause screen changes the item) */
#define CameraScreenByte 0x3EAE /* the level map's byte for the screen layer entry 0 has reached (the camera modes write it) */
#define MariaHitTimers 0xA35E /* her hit timer by the hit's kind (OBJ_HIT_TAKEN bits 0-2) (MariaHitReact) */
#define MariaCrashKinds 0xA3AD /* the item crash's object kind by item (zField93) (MariaCrashStart) */
#define MariaCrashSounds 0xA3B6 /* the sound an item crash starts with, by its kind less $0D; 0 none (MariaCrashStart) */
#define MariaItem4ByState 0xA4B2 /* item 4's throw by state: 0 animation $26, 1 animation $27, 2 none (MariaThrowItem) */
#define MariaCrashHandlers 0xA4F9 /* seven words by zCrashKind: the item crash's frame (MariaCrashFrame) */
#define MariaCrashPhases 0xA553 /* three words by zCrashPhase (MariaCrashPhase) */
#define MariaCrashPhasesB 0xA5C7 /* three words by zCrashPhase, for crash kind 0 (MariaCrashPhaseB) */
#define MariaWalkSpeeds 0xA6C4 /* her X speed by facing, two words (MariaSpeedWalk) */
#define MariaClimbFrames 0xAF2D /* her frame in a ledge's hold, by low or high ledge (MariaClimbHold) */
#define MariaClimbWork 0xAF2F /* her OBJ_WORK_A in a ledge's hold, by low or high ledge (MariaClimbHold) */
#define PlayerJumpStartYLo 0x3BF2 /* her Y on the map when the jump started (Y and ScrollYLo, ScrollYHiScreen and the carry) (MariaJumpStart) */
#define PlayerJumpStartYHi 0x3BF3 /* the high byte of PlayerJumpStartYLo */
#define zCrashKind 0x20D0 /* her item crash's kind less $0D: the index of its frame handlers (MariaCrashStart, MariaCrashFrame) */
#define zCrashPhase 0x20D1 /* her item crash's phase: the index of its phase handlers (MariaCrashPhase) */
#define zFieldD2 0x20D2 /* cleared when her item crash starts; her crash phases wait on it; the crash's objects set it */
#define MariaSlotPlaces 0xC6BD /* her companions' places beside her: X and Y offset pairs (MariaObjectPlaceByState) */
#define MariaSlotPlaceByState 0xC6D1 /* the first pair in MariaSlotPlaces by her state (MariaObjectPlaceByState) */
#define MariaFrameByPlayerFrame 0xD3D1 /* an object's frame by her frame less $53 (MariaObjectFrameByPlayerFrame) */
#define LayerPlaceOffsetsLoAlt 0xA77E /* the place offsets' low bytes ScrollXPlusOffset takes when ScrollOffsetSwitch is set, by the index word (0 ahead, 1 behind) */
#define LayerPlaceOffsetsLo 0xA780 /* the place offsets' low bytes by the index word (0 ahead, 1 behind): ScrollXPlusOffset, ScrollYPlusOffset, and DrawBlockColumn and DrawBlockRow for a ScrollColumnBlocks with bit 7 */
#define LayerPlaceOffsetsHi 0xA782 /* the place offsets' high bytes by the index word, for LayerPlaceOffsetsLo and LayerPlaceOffsetsLoAlt */
#define CameraWavePhase 0x3EBD /* the phase of the water camera's wave (CameraWaterWave counts it on) */
#define CameraModes 0xA0E6 /* the camera mode handlers by CameraMode, a word each (StageCameraModeDispatch) */
#define StageTerrainRead 0x8006 /* in a stage overlay: its terrain read at the point in zTemp00-03 (StageTileRead; Maria's object probes jump to it) */
#define MariaCompanionYOffsets 0xC63D /* a companion's Y offset from her by OBJ_WORK_E (its slot less one and bit 1 of the frame tick) (MariaObjectKind1) */
#define MariaCompanionXOffsets 0xC641 /* a companion's X offset from her by OBJ_WORK_E (MariaObjectKind1) */
#define MariaCompanionHandlers 0xC6F7 /* the handlers of her companions in slots 1 and 2 by OBJ_KIND, six words (MariaRunCompanionKind) */
#define MariaObjectHandlers 0xC73B /* the handlers of her objects in slots 3 to 15 by OBJ_KIND (MariaRunObjectSlot) */

#endif
